import type { LevelDef } from '../core';

// The shipped pack, generated by `npm run levels` (scripts/generate-pack.ts). Don't edit by hand.
const files = import.meta.glob<LevelDef>('./pack/*.json', { eager: true, import: 'default' });

/** Every level in play order (index 0 is level 1). */
export const LEVELS: readonly LevelDef[] = Object.keys(files)
  .sort()
  .map((path) => files[path] as LevelDef);

/** Level by its 1-based number, or undefined past the end. */
export function getLevel(number: number): LevelDef | undefined {
  return LEVELS[number - 1];
}
